import { UsageError } from './errors.js';

export const DEFAULT_MAX_TEXT_LENGTH = 500;
export const DEFAULT_LOCK_TIMEOUT_MS = 5_000;
export const DEFAULT_STALE_LOCK_MS = 10_000;

const POSITIVE_INTEGER = /^[1-9]\d*$/;

function readPositiveInteger(env, name, fallback) {
  const raw = env[name];
  if (raw === undefined || raw === '') {
    return fallback;
  }
  const value = Number(raw);
  if (!POSITIVE_INTEGER.test(raw) || !Number.isSafeInteger(value)) {
    throw new UsageError(`Environment variable ${name} must be a positive whole number, got ${JSON.stringify(raw)}.`);
  }
  return value;
}

/**
 * Reads the configurable limits from environment variables, falling back to
 * the defaults above. Throws `UsageError` on malformed values instead of
 * silently ignoring them.
 */
export function loadConfig(env = {}) {
  return {
    maxTextLength: readPositiveInteger(env, 'TODO_MAX_TEXT_LENGTH', DEFAULT_MAX_TEXT_LENGTH),
    lockTimeoutMs: readPositiveInteger(env, 'TODO_LOCK_TIMEOUT_MS', DEFAULT_LOCK_TIMEOUT_MS),
    staleLockMs: readPositiveInteger(env, 'TODO_STALE_LOCK_MS', DEFAULT_STALE_LOCK_MS),
  };
}

