import { DEFAULT_MAX_TEXT_LENGTH } from './config.js';
import { NotFoundError, StorageError, ValidationError } from './errors.js';
import { escapeControlCharacters } from './format.js';

const CONTROL_CHARACTER = /\p{Cc}/u;
const DIGITS_ONLY = /^\d+$/;
const MAX_ID_ECHO_LENGTH = 40;

/**
 * State shape shared by every operation: `nextId` is the id the next `add`
 * will use. It only grows, so ids of deleted todos are never handed out again.
 */
export function createEmptyState() {
  return { nextId: 1, todos: [] };
}

/**
 * Trims `rawText` and checks it is non-empty, single-line, and at most
 * `maxLength` Unicode code points (not UTF-16 units, so an emoji counts as one).
 */
export function normalizeText(rawText, { maxLength = DEFAULT_MAX_TEXT_LENGTH } = {}) {
  if (typeof rawText !== 'string') {
    throw new ValidationError(`Todo text must be a string, got ${typeof rawText}.`);
  }
  const text = rawText.trim();
  if (text.length === 0) {
    throw new ValidationError('Todo text cannot be empty or only whitespace.');
  }
  if (CONTROL_CHARACTER.test(text)) {
    throw new ValidationError('Todo text must be a single line without control characters such as newlines or tabs.');
  }
  const length = [...text].length;
  if (length > maxLength) {
    throw new ValidationError(`Todo text is too long (${length} characters; the maximum is ${maxLength}).`);
  }
  return text;
}

function describeRawId(rawId) {
  const display = escapeControlCharacters(String(rawId));
  const truncated = [...display].length > MAX_ID_ECHO_LENGTH
    ? `${[...display].slice(0, MAX_ID_ECHO_LENGTH).join('')}…`
    : display;
  return `"${truncated}"`;
}

/** Parses a user-supplied id. Accepts only decimal digits that form a safe integer ≥ 1. */
export function parseId(rawId) {
  const text = String(rawId);
  const id = Number(text);
  if (!DIGITS_ONLY.test(text) || !Number.isSafeInteger(id) || id < 1) {
    throw new ValidationError(`Invalid id ${describeRawId(rawId)}: expected a positive whole number such as 1 or 42.`);
  }
  return id;
}

function findTodoIndex(state, id) {
  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new NotFoundError(`No todo with id ${id}. Run "node index.js list" to see existing ids.`);
  }
  return index;
}

/** Returns `{ state, todo }` with a new pending todo appended. */
export function addTodo(state, rawText, { now = new Date(), maxTextLength } = {}) {
  const text = normalizeText(rawText, { maxLength: maxTextLength });
  const id = state.nextId;
  if (!Number.isSafeInteger(id + 1)) {
    throw new StorageError(`Cannot add a todo: the id counter (${id}) has reached the largest supported value.`);
  }
  const todo = { id, text, completed: false, createdAt: now.toISOString() };
  return {
    state: { nextId: id + 1, todos: [...state.todos, todo] },
    todo,
  };
}

/**
 * Returns `{ state, todo, changed }`. Completing an already completed todo is
 * a no-op (`changed: false`, same `state` object) rather than an error.
 */
export function completeTodo(state, id) {
  const index = findTodoIndex(state, id);
  const existing = state.todos[index];
  if (existing.completed) {
    return { state, todo: existing, changed: false };
  }
  const todo = { ...existing, completed: true };
  return {
    state: { ...state, todos: state.todos.with(index, todo) },
    todo,
    changed: true,
  };
}

/** Returns `{ state, todo }` where `todo` is the removed item. `nextId` is left unchanged. */
export function deleteTodo(state, id) {
  const index = findTodoIndex(state, id);
  return {
    state: { ...state, todos: state.todos.toSpliced(index, 1) },
    todo: state.todos[index],
  };
}

