import { randomUUID } from 'node:crypto';
import { open, readFile, rename, stat, unlink } from 'node:fs/promises';
import path from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';

import { DEFAULT_LOCK_TIMEOUT_MS, DEFAULT_STALE_LOCK_MS } from './config.js';
import { StorageError } from './errors.js';
import { createEmptyState } from './todos.js';

export const TODO_FILE_NAME = 'todos.json';
const LOCK_RETRY_DELAY_MS = 20;
const BYTE_ORDER_MARK = '﻿';

/** Path of the todo file for a working directory. */
export function resolveTodoFile(cwd) {
  return path.join(cwd, TODO_FILE_NAME);
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isPositiveSafeInteger(value) {
  return Number.isSafeInteger(value) && value >= 1;
}

function validateTodo(todo, index, fail) {
  const where = `todo at index ${index}`;
  if (!isPlainObject(todo)) {
    fail(`${where} is not an object`);
  }
  if (!isPositiveSafeInteger(todo.id)) {
    fail(`${where} has an invalid "id" (expected a positive integer, got ${JSON.stringify(todo.id)})`);
  }
  if (typeof todo.text !== 'string' || todo.text.trim() === '') {
    fail(`${where} (id ${todo.id}) has an invalid "text" (expected a non-empty string)`);
  }
  if (typeof todo.completed !== 'boolean') {
    fail(`${where} (id ${todo.id}) has an invalid "completed" (expected true or false)`);
  }
  if (typeof todo.createdAt !== 'string' || Number.isNaN(Date.parse(todo.createdAt))) {
    fail(`${where} (id ${todo.id}) has an invalid "createdAt" (expected an ISO 8601 timestamp)`);
  }
}

/**
