import { randomUUID } from 'node:crypto';
import { open, readFile, rename, stat, unlink } from 'node:fs/promises';
import path from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';

import { DEFAULT_LOCK_TIMEOUT_MS, DEFAULT_STALE_LOCK_MS } from './config.js';
import { StorageError } from './errors.js';
import { createEmptyState } from './todos.js';

export const TODO_FILE_NAME = 'todos.json';
const LOCK_RETRY_DELAY_MS = 20;
const BYTE_ORDER_MARK = '﻿';

/** Path of the todo file for a working directory. */
export function resolveTodoFile(cwd) {
  return path.join(cwd, TODO_FILE_NAME);
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isPositiveSafeInteger(value) {
  return Number.isSafeInteger(value) && value >= 1;
}

function validateTodo(todo, index, fail) {
  const where = `todo at index ${index}`;
  if (!isPlainObject(todo)) {
    fail(`${where} is not an object`);
  }
  if (!isPositiveSafeInteger(todo.id)) {
    fail(`${where} has an invalid "id" (expected a positive integer, got ${JSON.stringify(todo.id)})`);
  }
  if (typeof todo.text !== 'string' || todo.text.trim() === '') {
    fail(`${where} (id ${todo.id}) has an invalid "text" (expected a non-empty string)`);
  }
  if (typeof todo.completed !== 'boolean') {
    fail(`${where} (id ${todo.id}) has an invalid "completed" (expected true or false)`);
  }
  if (typeof todo.createdAt !== 'string' || Number.isNaN(Date.parse(todo.createdAt))) {
    fail(`${where} (id ${todo.id}) has an invalid "createdAt" (expected an ISO 8601 timestamp)`);
  }
}

/**
 * Validates parsed JSON and returns a state object. Accepts the current
 * `{ nextId, todos }` shape and a bare array of todos (for hand-written or
 * older files), deriving `nextId` from the highest id when it is missing or
 * too small.
 */
export function validateState(data, source = TODO_FILE_NAME) {
  const fail = (reason) => {
    throw new StorageError(`${source} is invalid: ${reason}. Fix the file by hand or move it aside to start over.`);
  };

  let todos;
  let storedNextId;
  if (Array.isArray(data)) {
    todos = data;
  } else if (isPlainObject(data) && Array.isArray(data.todos)) {
    todos = data.todos;
    storedNextId = data.nextId;
    if (storedNextId !== undefined && !isPositiveSafeInteger(storedNextId)) {
      fail(`"nextId" must be a positive integer, got ${JSON.stringify(storedNextId)}`);
    }
  } else {
    fail('expected an object with a "todos" array');
  }

  const seenIds = new Set();
  let maxId = 0;
  todos.forEach((todo, index) => {
    validateTodo(todo, index, fail);
    if (seenIds.has(todo.id)) {
      fail(`id ${todo.id} appears more than once`);
    }
    seenIds.add(todo.id);
    maxId = Math.max(maxId, todo.id);
  });

  return {
    nextId: Math.max(storedNextId ?? 1, maxId + 1),
    todos: todos.map((todo) => ({ ...todo })),
  };
}

/** Parses the raw file contents. Empty or whitespace-only content is an empty list. */
export function parseState(raw, source = TODO_FILE_NAME) {
  const content = raw.startsWith(BYTE_ORDER_MARK) ? raw.slice(BYTE_ORDER_MARK.length) : raw;
  if (content.trim() === '') {
    return createEmptyState();
  }
  let data;
  try {
    data = JSON.parse(content);
  } catch (error) {
    throw new StorageError(
      `${source} is not valid JSON (${error.message}). Fix the file by hand or move it aside to start over.`,
      { cause: error },
    );
  }
  return validateState(data, source);
}

/** Reads and validates the todo file. A missing file is an empty list; nothing is created. */
export async function loadState(filePath) {
  let raw;
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      return createEmptyState();
    }
    throw new StorageError(`Could not read ${filePath}: ${error.message}`, { cause: error });
  }
  return parseState(raw, filePath);
}

/** Converts state to the on-disk JSON text: pretty-printed with a trailing newline. */
export function serializeState(state) {
  return `${JSON.stringify({ nextId: state.nextId, todos: state.todos }, null, 2)}\n`;
}

/**
 * Writes state atomically: the JSON goes to a unique temp file in the same
 * directory, is flushed to disk, then renamed over the target. Readers see
 * either the old file or the new one, never a partial write.
 */
export async function saveState(filePath, state) {
  const tempPath = `${filePath}.${process.pid}.${randomUUID()}.tmp`;
  try {
    const handle = await open(tempPath, 'wx');
    try {
      await handle.writeFile(serializeState(state), 'utf8');
      await handle.sync();
    } finally {
      await handle.close();
    }
    await rename(tempPath, filePath);
  } catch (error) {
    let message = `Could not write ${filePath}: ${error.message}`;
    try {
      await unlink(tempPath);
    } catch (cleanupError) {
      if (cleanupError.code !== 'ENOENT') {
        message += ` (also failed to remove temporary file ${tempPath}: ${cleanupError.message})`;
      }
    }
    throw new StorageError(message, { cause: error });
  }
}

/**
 * Removes the lock if its last modification is older than `staleLockMs`,
 * which means its owner most likely crashed. Returns true when the caller
 * should retry acquiring immediately.
 */
async function clearStaleLock(lockPath, staleLockMs) {
  let lockStat;
  try {
    lockStat = await stat(lockPath);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return true;
    }
    throw new StorageError(`Could not inspect lock file ${lockPath}: ${error.message}`, { cause: error });
  }
  if (Date.now() - lockStat.mtimeMs <= staleLockMs) {
    return false;
  }
  try {
    await unlink(lockPath);
  } catch (error) {
    if (error.code !== 'ENOENT') {
      throw new StorageError(`Could not remove stale lock file ${lockPath}: ${error.message}`, { cause: error });
    }
  }
  return true;
}

async function acquireLock(lockPath, { timeoutMs, staleLockMs }) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      const handle = await open(lockPath, 'wx');
      try {
        await handle.writeFile(`${process.pid}\n`, 'utf8');
      } finally {
        await handle.close();
      }
      return;
    } catch (error) {
      if (error.code !== 'EEXIST') {
        throw new StorageError(`Could not create lock file ${lockPath}: ${error.message}`, { cause: error });
      }
    }
    if (await clearStaleLock(lockPath, staleLockMs)) {
      continue;
    }
    if (Date.now() >= deadline) {
      throw new StorageError(
        `Timed out after ${timeoutMs}ms waiting for another todo command to release ${lockPath}. ` +
          'If no other todo command is running, delete that file and try again.',
      );
    }
    await delay(LOCK_RETRY_DELAY_MS);
  }
}

async function releaseLock(lockPath) {
  try {
    await unlink(lockPath);
  } catch (error) {
    // ENOENT means another process judged our lock stale and removed it;
    // there is nothing left to release.
    if (error.code !== 'ENOENT') {
      throw new StorageError(`Could not remove lock file ${lockPath}: ${error.message}. Delete it by hand.`, {
        cause: error,
      });
    }
  }
}

/**
 * Runs `fn` while holding an exclusive `<filePath>.lock` file, so concurrent
 * CLI processes cannot interleave their read-modify-write cycles. Waits up to
 * `timeoutMs` for the lock; locks untouched for `staleLockMs` are reclaimed.
 */
export async function withFileLock(
  filePath,
  fn,
  { timeoutMs = DEFAULT_LOCK_TIMEOUT_MS, staleLockMs = DEFAULT_STALE_LOCK_MS } = {},
) {
  const lockPath = `${filePath}.lock`;
  await acquireLock(lockPath, { timeoutMs, staleLockMs });
  try {
    return await fn();
  } finally {
    await releaseLock(lockPath);
  }
}

/**
 * Loads state under the lock, passes it to `update`, and saves the result if
 * `update` returns `{ changed: true }` (or omits `changed`). Returns whatever
 * `update` returned. If `update` throws, nothing is written.
 */
export function updateState(filePath, update, lockOptions) {
  return withFileLock(
    filePath,
    async () => {
      const result = update(await loadState(filePath));
      if (result.changed !== false) {
        await saveState(filePath, result.state);
      }
      return result;
    },
    lockOptions,
  );
}

