import { loadConfig } from './config.js';
import { EXIT_CODES, TodoError, UsageError } from './errors.js';
import { escapeControlCharacters, formatTodoList } from './format.js';
import { loadState, resolveTodoFile, updateState } from './storage.js';
import { addTodo, completeTodo, deleteTodo, normalizeText, parseId } from './todos.js';

export const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo (quotes optional: add Buy milk)
  list             Show all todos with their status
  complete <id>    Mark a todo as done
  delete <id>      Remove a todo
  help             Show this message

Todos are stored in ./todos.json.`;

function describeTodo(todo) {
  return `todo ${todo.id}: ${escapeControlCharacters(todo.text)}`;
}

function requireNoArguments(command, args) {
  if (args.length > 0) {
    throw new UsageError(`"${command}" does not take arguments.`);
  }
}

function requireSingleId(command, args) {
  if (args.length === 0) {
    throw new UsageError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  if (args.length > 1) {
    throw new UsageError(`Too many arguments for "${command}": expected one id, got ${args.length}.`);
  }
  return parseId(args[0]);
}

async function addCommand(args, context) {
  if (args.length === 0) {
    throw new UsageError('Missing todo text. Usage: node index.js add "Buy groceries"');
  }
  // Validate before taking the lock so bad input is reported even when the file is busy or corrupt.
  const text = normalizeText(args.join(' '), { maxLength: context.config.maxTextLength });
  const { todo } = await updateState(
    context.filePath,
    (state) => addTodo(state, text, { now: context.now(), maxTextLength: context.config.maxTextLength }),
    context.lockOptions,
  );
  return `Added ${describeTodo(todo)}`;
}

async function listCommand(args, context) {
  requireNoArguments('list', args);
  const { todos } = await loadState(context.filePath);
  return formatTodoList(todos);
}

async function completeCommand(args, context) {
  const id = requireSingleId('complete', args);
  const { todo, changed } = await updateState(context.filePath, (state) => completeTodo(state, id), context.lockOptions);
  return changed ? `Completed ${describeTodo(todo)}` : `Todo ${todo.id} is already completed: ${escapeControlCharacters(todo.text)}`;
}

async function deleteCommand(args, context) {
  const id = requireSingleId('delete', args);
  const { todo } = await updateState(context.filePath, (state) => deleteTodo(state, id), context.lockOptions);
  return `Deleted ${describeTodo(todo)}`;
}

async function helpCommand() {
  return USAGE;
}

const COMMANDS = new Map([
  ['add', addCommand],
  ['list', listCommand],
  ['complete', completeCommand],
  ['delete', deleteCommand],
  ['help', helpCommand],
  ['--help', helpCommand],
  ['-h', helpCommand],
]);

function reportError(error, stderr) {
  if (error instanceof TodoError) {
    stderr.write(`Error: ${error.message}\n`);
    if (error instanceof UsageError) {
      stderr.write(`\n${USAGE}\n`);
    }
    return error.exitCode;
  }
  stderr.write(`Unexpected error (this is a bug): ${error?.stack ?? String(error)}\n`);
  return EXIT_CODES.FAILURE;
}

/**
 * Runs one CLI invocation and resolves with the process exit code. Never
 * throws: expected failures go to `stderr` as a one-line message, unexpected
 * ones with their stack trace.
 *
 * @param {string[]} argv Arguments after `node index.js`.
 * @param {object} [options] Injection points for tests.
 * @param {string} [options.cwd] Directory holding todos.json.
 * @param {Record<string, string | undefined>} [options.env] Source of `TODO_*` limits.
 * @param {{ write(chunk: string): unknown }} [options.stdout]
 * @param {{ write(chunk: string): unknown }} [options.stderr]
 * @param {() => Date} [options.now] Clock used for `createdAt`.
 * @returns {Promise<number>}
 */
export async function run(
  argv,
  {
    cwd = process.cwd(),
    env = process.env,
    stdout = process.stdout,
    stderr = process.stderr,
    now = () => new Date(),
  } = {},
) {
  try {
    const config = loadConfig(env);
    const [commandName, ...args] = argv;
    if (commandName === undefined) {
      throw new UsageError('No command given.');
    }
    const command = COMMANDS.get(commandName);
    if (command === undefined) {
      throw new UsageError(`Unknown command "${escapeControlCharacters(commandName)}".`);
    }
    const output = await command(args, {
      filePath: resolveTodoFile(cwd),
      config,
      now,
      lockOptions: { timeoutMs: config.lockTimeoutMs, staleLockMs: config.staleLockMs },
    });
    stdout.write(`${output}\n`);
    return EXIT_CODES.SUCCESS;
  } catch (error) {
    return reportError(error, stderr);
  }
}

