import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { NotFoundError, StorageError, ValidationError } from '../src/errors.js';
import { addTodo, completeTodo, createEmptyState, deleteTodo, normalizeText, parseId } from '../src/todos.js';

const FIXED_NOW = new Date('2026-01-02T03:04:05.678Z');

function stateWith(...todos) {
  return {
    nextId: todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1,
    todos,
  };
}

function todo(id, overrides = {}) {
  return { id, text: `task ${id}`, completed: false, createdAt: FIXED_NOW.toISOString(), ...overrides };
}

describe('normalizeText', () => {
  it('trims surrounding whitespace', () => {
    assert.equal(normalizeText('  Buy groceries \n'), 'Buy groceries');
  });

  it('keeps inner spacing and punctuation as typed', () => {
    assert.equal(normalizeText('Call  Mom -- re: "plans"'), 'Call  Mom -- re: "plans"');
  });

  for (const [label, input] of [
