import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { escapeControlCharacters, formatTodoLine, formatTodoList } from '../src/format.js';

const CREATED_AT = '2026-01-02T03:04:05.678Z';

function todo(id, text, completed = false) {
  return { id, text, completed, createdAt: CREATED_AT };
}

describe('formatTodoLine', () => {
  it('shows "[ ]" for a pending todo', () => {
    assert.equal(formatTodoLine(todo(1, 'Buy groceries')), '1. [ ] Buy groceries');
  });

  it('shows "[x]" for a completed todo', () => {
    assert.equal(formatTodoLine(todo(3, 'Pay rent', true)), '3. [x] Pay rent');
  });

  it('pads short ids so status columns line up', () => {
    assert.equal(formatTodoLine(todo(7, 'a'), 3), '7.   [ ] a');
  });
});

describe('formatTodoList', () => {
  it('returns a helpful message for an empty list', () => {
    assert.match(formatTodoList([]), /^No todos yet\. Add one with: node index\.js add/);
  });

