import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import {
  DEFAULT_LOCK_TIMEOUT_MS,
  DEFAULT_MAX_TEXT_LENGTH,
  DEFAULT_STALE_LOCK_MS,
  loadConfig,
} from '../src/config.js';
import { UsageError } from '../src/errors.js';

describe('loadConfig', () => {
  it('returns the defaults when no variables are set', () => {
    assert.deepEqual(loadConfig({}), {
      maxTextLength: DEFAULT_MAX_TEXT_LENGTH,
      lockTimeoutMs: DEFAULT_LOCK_TIMEOUT_MS,
      staleLockMs: DEFAULT_STALE_LOCK_MS,
    });
  });

  it('treats an empty value as unset', () => {
    assert.equal(loadConfig({ TODO_MAX_TEXT_LENGTH: '' }).maxTextLength, DEFAULT_MAX_TEXT_LENGTH);
  });

  it('reads each limit from its environment variable', () => {
    assert.deepEqual(
      loadConfig({ TODO_MAX_TEXT_LENGTH: '80', TODO_LOCK_TIMEOUT_MS: '250', TODO_STALE_LOCK_MS: '1000' }),
      { maxTextLength: 80, lockTimeoutMs: 250, staleLockMs: 1000 },
    );
  });

  it('accepts the boundary value 1', () => {
    assert.equal(loadConfig({ TODO_MAX_TEXT_LENGTH: '1' }).maxTextLength, 1);
  });

  for (const bad of ['0', '-5', '1.5', 'ten', ' 10', '1e3', '99999999999999999999']) {
    it(`rejects TODO_MAX_TEXT_LENGTH=${JSON.stringify(bad)} and names the variable`, () => {
      assert.throws(() => loadConfig({ TODO_MAX_TEXT_LENGTH: bad }), (error) => {
        assert.ok(error instanceof UsageError);
        assert.match(error.message, /TODO_MAX_TEXT_LENGTH must be a positive whole number/);
        return true;
      });
    });
  }
});

