const canTestPermissions = process.platform !== 'win32' && process.getuid?.() !== 0;

function todo(id, overrides = {}) {
  return { id, text: `task ${id}`, completed: false, createdAt: CREATED_AT, ...overrides };
}

describe('storage', () => {
  let dir;
  let filePath;

  beforeEach(async () => {
    dir = await makeTempDir();
    filePath = resolveTodoFile(dir);
  });

  afterEach(async () => {
    await removeTempDir(dir);
  });

  describe('loadState', () => {
    it('returns an empty state when todos.json does not exist, without creating it', async () => {
      assert.deepEqual(await loadState(filePath), { nextId: 1, todos: [] });
      assert.deepEqual(await listDir(dir), []);
    });

    it('round-trips state written by saveState', async () => {
      const state = { nextId: 5, todos: [todo(1), todo(4, { completed: true, text: 'Café ☕' })] };
      await saveState(filePath, state);
      assert.deepEqual(await loadState(filePath), state);
    });

    it('loads a legacy bare array and derives nextId from the highest id', async () => {
      await writeFile(filePath, JSON.stringify([todo(2), todo(7)]));
      const state = await loadState(filePath);
      assert.equal(state.nextId, 8);
      assert.deepEqual(state.todos.map((t) => t.id), [2, 7]);
    });

    it('raises a nextId that is lower than an existing id, so ids stay unique', async () => {
      await writeFile(filePath, JSON.stringify({ nextId: 2, todos: [todo(5)] }));
      assert.equal((await loadState(filePath)).nextId, 6);
    });

    it('accepts a missing nextId in the object format', async () => {
      await writeFile(filePath, JSON.stringify({ todos: [todo(3)] }));
      assert.equal((await loadState(filePath)).nextId, 4);
    });

    it('treats an empty or whitespace-only file as an empty list', async () => {
      for (const content of ['', '  \n\t ']) {
        await writeFile(filePath, content);
        assert.deepEqual(await loadState(filePath), { nextId: 1, todos: [] });
      }
    });

    it('ignores a UTF-8 byte order mark left by some editors', async () => {
      await writeFile(filePath, `\uFEFF${JSON.stringify({ nextId: 2, todos: [todo(1)] })}`);
      assert.equal((await loadState(filePath)).todos.length, 1);
    });

    it('preserves unknown per-todo fields so hand-added data is not lost on rewrite', async () => {
      await writeFile(filePath, JSON.stringify({ nextId: 2, todos: [todo(1, { priority: 'high' })] }));
      assert.equal((await loadState(filePath)).todos[0].priority, 'high');
    });

    it('reports invalid JSON with the file path and leaves the file untouched', async () => {
      await writeFile(filePath, '{"todos": [');
      await assert.rejects(loadState(filePath), (error) => {
        assert.ok(error instanceof StorageError);
        assert.match(error.message, /is not valid JSON/);
        assert.ok(error.message.includes(filePath));
        assert.ok(error.cause instanceof SyntaxError);
        return true;
      });
      assert.equal(await readFile(filePath, 'utf8'), '{"todos": [');
    });

    it('wraps read failures other than a missing file in StorageError', async () => {
      await mkdir(filePath);
      await assert.rejects(loadState(filePath), { name: 'StorageError', message: /Could not read/ });
    });
  });

  describe('parseState validation', () => {
    const invalidCases = [
      ['a number at the root', 42, /expected an object with a "todos" array/],
      ['null at the root', null, /expected an object with a "todos" array/],
      ['an object without todos', { items: [] }, /expected an object with a "todos" array/],
      ['a non-integer nextId', { nextId: 1.5, todos: [] }, /"nextId" must be a positive integer/],
      ['a zero nextId', { nextId: 0, todos: [] }, /"nextId" must be a positive integer/],
      ['a todo that is not an object', [null], /todo at index 0 is not an object/],
      ['a string id', [todo('1')], /invalid "id"/],
      ['a negative id', [todo(-1)], /invalid "id"/],
      ['a missing text', [{ ...todo(1), text: undefined }], /invalid "text"/],
      ['a blank text', [todo(1, { text: '  ' })], /invalid "text"/],
      ['a string completed flag', [todo(1, { completed: 'yes' })], /invalid "completed"/],
      ['an unparseable createdAt', [todo(1, { createdAt: 'yesterday' })], /invalid "createdAt"/],
      ['duplicate ids', [todo(1), todo(1)], /id 1 appears more than once/],
    ];

