        assert.throws(() => parseState(JSON.stringify(data), 'todos.json'), (error) => {
          assert.ok(error instanceof StorageError, `expected StorageError, got ${error.name}`);
          assert.match(error.message, pattern);
          assert.match(error.message, /Fix the file by hand or move it aside/);
          return true;
        });
      });
    }

