    it('writes pretty-printed JSON with a trailing newline in the { nextId, todos } shape', async () => {
      const state = { nextId: 2, todos: [todo(1)] };
      await saveState(filePath, state);
      const raw = await readFile(filePath, 'utf8');
      assert.equal(raw, serializeState(state));
      assert.ok(raw.endsWith('}\n'));
      assert.deepEqual(JSON.parse(raw), state);
    });

    it('replaces the previous contents entirely', async () => {
      await saveState(filePath, { nextId: 3, todos: [todo(1), todo(2)] });
      await saveState(filePath, { nextId: 3, todos: [] });
      assert.deepEqual(JSON.parse(await readFile(filePath, 'utf8')), { nextId: 3, todos: [] });
    });

    it('leaves no temporary files behind', async () => {
      await saveState(filePath, { nextId: 1, todos: [] });
      assert.deepEqual(await listDir(dir), ['todos.json']);
    });

    it('fails with StorageError and no temp files when the directory is not writable', { skip: !canTestPermissions }, async () => {
      await chmod(dir, 0o555);
      try {
        await assert.rejects(saveState(filePath, { nextId: 1, todos: [] }), {
          name: 'StorageError',
          message: /Could not write .*todos\.json/,
        });
      } finally {
        await chmod(dir, 0o755);
      }
      assert.deepEqual(await listDir(dir), []);
    });
  });

  describe('withFileLock', () => {
    it('returns the callback result and removes the lock file afterwards', async () => {
      const result = await withFileLock(filePath, async () => {
        assert.ok((await listDir(dir)).includes('todos.json.lock'), 'lock should exist while running');
        return 'done';
      });
      assert.equal(result, 'done');
      assert.deepEqual(await listDir(dir), []);
    });

    it('removes the lock file and rethrows when the callback fails', async () => {
      const failure = new Error('boom');
      await assert.rejects(withFileLock(filePath, async () => { throw failure; }), (error) => error === failure);
      assert.deepEqual(await listDir(dir), []);
    });

    it('times out with an actionable message while another holder keeps a fresh lock', async () => {
      await writeFile(`${filePath}.lock`, '12345\n');
      const started = Date.now();
      await assert.rejects(withFileLock(filePath, async () => 'never', { timeoutMs: 100, staleLockMs: 60_000 }), {
        name: 'StorageError',
        message: /Timed out after 100ms .*delete that file and try again/,
      });
      assert.ok(Date.now() - started >= 100, 'should wait at least the timeout');
      assert.ok((await listDir(dir)).includes('todos.json.lock'), 'a live lock must not be removed');
    });

    it('reclaims a stale lock left behind by a crashed process', async () => {
      const lockPath = `${filePath}.lock`;
      await writeFile(lockPath, '12345\n');
      const longAgo = new Date(Date.now() - 60_000);
      await utimes(lockPath, longAgo, longAgo);
      const result = await withFileLock(filePath, async () => 'ran', { timeoutMs: 100, staleLockMs: 1_000 });
      assert.equal(result, 'ran');
      assert.deepEqual(await listDir(dir), []);
    });

    it('serializes concurrent in-process updates so no add is lost', async () => {
      const count = 25;
      const now = new Date(CREATED_AT);
      await Promise.all(
        Array.from({ length: count }, (_, index) =>
          updateState(filePath, (state) => addTodo(state, `parallel ${index}`, { now })),
        ),
      );
      const state = await loadState(filePath);
      assert.equal(state.todos.length, count);
      assert.deepEqual(state.todos.map((t) => t.id).sort((a, b) => a - b), Array.from({ length: count }, (_, i) => i + 1));
      assert.equal(state.nextId, count + 1);
    });
  });

  describe('updateState', () => {
    it('writes nothing when the update throws', async () => {
      const original = '{"nextId":2,"todos":[{"id":1,"text":"a","completed":false,"createdAt":"2026-01-02T03:04:05.678Z"}]}';
      await writeFile(filePath, original);
      await assert.rejects(updateState(filePath, () => { throw new StorageError('nope'); }), { message: 'nope' });
      assert.equal(await readFile(filePath, 'utf8'), original);
      assert.deepEqual((await listDir(dir)).sort(), ['todos.json']);
    });

    it('skips the write when the update reports changed: false', async () => {
      const compact = JSON.stringify({ nextId: 2, todos: [todo(1)] });
      await writeFile(filePath, compact);
      await updateState(filePath, (state) => ({ state, changed: false }));
      assert.equal(await readFile(filePath, 'utf8'), compact, 'file should keep its original formatting');
    });

    it('creates todos.json on the first successful write', async () => {
      await updateState(filePath, (state) => addTodo(state, 'first', { now: new Date(CREATED_AT) }));
      assert.deepEqual(await listDir(dir), ['todos.json']);
      assert.equal((await loadState(filePath)).todos[0].text, 'first');
    });
  });

  it('resolveTodoFile places todos.json directly inside the given directory', () => {
    assert.equal(resolveTodoFile('/some/dir'), path.join('/some/dir', 'todos.json'));
  });
});

