import assert from 'node:assert/strict';
import { chmod, mkdir, readFile, utimes, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { afterEach, beforeEach, describe, it } from 'node:test';

import { StorageError } from '../src/errors.js';
import {
  loadState,
  parseState,
  resolveTodoFile,
  saveState,
  serializeState,
  updateState,
  withFileLock,
} from '../src/storage.js';
import { addTodo } from '../src/todos.js';
import { listDir, makeTempDir, removeTempDir } from './helpers/harness.js';

const CREATED_AT = '2026-01-02T03:04:05.678Z';
const canTestPermissions = process.platform !== 'win32' && process.getuid?.() !== 0;

function todo(id, overrides = {}) {
  return { id, text: `task ${id}`, completed: false, createdAt: CREATED_AT, ...overrides };
}

describe('storage', () => {
  let dir;
  let filePath;

  beforeEach(async () => {
    dir = await makeTempDir();
    filePath = resolveTodoFile(dir);
  });

  afterEach(async () => {
    await removeTempDir(dir);
  });

  describe('loadState', () => {
    it('returns an empty state when todos.json does not exist, without creating it', async () => {
      assert.deepEqual(await loadState(filePath), { nextId: 1, todos: [] });
      assert.deepEqual(await listDir(dir), []);
    });

    it('round-trips state written by saveState', async () => {
      const state = { nextId: 5, todos: [todo(1), todo(4, { completed: true, text: 'Café ☕' })] };
      await saveState(filePath, state);
      assert.deepEqual(await loadState(filePath), state);
    });

    it('loads a legacy bare array and derives nextId from the highest id', async () => {
      await writeFile(filePath, JSON.stringify([todo(2), todo(7)]));
      const state = await loadState(filePath);
      assert.equal(state.nextId, 8);
      assert.deepEqual(state.todos.map((t) => t.id), [2, 7]);
    });

    it('raises a nextId that is lower than an existing id, so ids stay unique', async () => {
      await writeFile(filePath, JSON.stringify({ nextId: 2, todos: [todo(5)] }));
      assert.equal((await loadState(filePath)).nextId, 6);
    });

    it('accepts a missing nextId in the object format', async () => {
      await writeFile(filePath, JSON.stringify({ todos: [todo(3)] }));
      assert.equal((await loadState(filePath)).nextId, 4);
    });

    it('treats an empty or whitespace-only file as an empty list', async () => {
      for (const content of ['', '  \n\t ']) {
        await writeFile(filePath, content);
        assert.deepEqual(await loadState(filePath), { nextId: 1, todos: [] });
      }
    });

    it('ignores a UTF-8 byte order mark left by some editors', async () => {
      await writeFile(filePath, `﻿${JSON.stringify({ nextId: 2, todos: [todo(1)] })}`);
      assert.equal((await loadState(filePath)).todos.length, 1);
    });

    it('preserves unknown per-todo fields so hand-added data is not lost on rewrite', async () => {
      await writeFile(filePath, JSON.stringify({ nextId: 2, todos: [todo(1, { priority: 'high' })] }));
      assert.equal((await loadState(filePath)).todos[0].priority, 'high');
    });

    it('reports invalid JSON with the file path and leaves the file untouched', async () => {
      await writeFile(filePath, '{"todos": [');
      await assert.rejects(loadState(filePath), (error) => {
        assert.ok(error instanceof StorageError);
        assert.match(error.message, /is not valid JSON/);
        assert.ok(error.message.includes(filePath));
        assert.ok(error.cause instanceof SyntaxError);
        return true;
      });
      assert.equal(await readFile(filePath, 'utf8'), '{"todos": [');
    });

    it('wraps read failures other than a missing file in StorageError', async () => {
      await mkdir(filePath);
      await assert.rejects(loadState(filePath), { name: 'StorageError', message: /Could not read/ });
    });
  });

  describe('parseState validation', () => {
    const invalidCases = [
      ['a number at the root', 42, /expected an object with a "todos" array/],
      ['null at the root', null, /expected an object with a "todos" array/],
      ['an object without todos', { items: [] }, /expected an object with a "todos" array/],
      ['a non-integer nextId', { nextId: 1.5, todos: [] }, /"nextId" must be a positive integer/],
      ['a zero nextId', { nextId: 0, todos: [] }, /"nextId" must be a positive integer/],
      ['a todo that is not an object', [null], /todo at index 0 is not an object/],
      ['a string id', [todo('1')], /invalid "id"/],
      ['a negative id', [todo(-1)], /invalid "id"/],
      ['a missing text', [{ ...todo(1), text: undefined }], /invalid "text"/],
      ['a blank text', [todo(1, { text: '  ' })], /invalid "text"/],
      ['a string completed flag', [todo(1, { completed: 'yes' })], /invalid "completed"/],
      ['an unparseable createdAt', [todo(1, { createdAt: 'yesterday' })], /invalid "createdAt"/],
      ['duplicate ids', [todo(1), todo(1)], /id 1 appears more than once/],
    ];

    for (const [label, data, pattern] of invalidCases) {
      it(`rejects ${label}`, () => {
        assert.throws(() => parseState(JSON.stringify(data), 'todos.json'), (error) => {
          assert.ok(error instanceof StorageError, `expected StorageError, got ${error.name}`);
          assert.match(error.message, pattern);
          assert.match(error.message, /Fix the file by hand or move it aside/);
          return true;
        });
      });
    }

    it('does not mutate the parsed input when validating it', () => {
      const raw = JSON.stringify({ nextId: 1, todos: [todo(4)] });
      parseState(raw);
      assert.equal(raw, JSON.stringify({ nextId: 1, todos: [todo(4)] }));
    });
  });

  describe('saveState', () => {
    it('writes pretty-printed JSON with a trailing newline in the { nextId, todos } shape', async () => {
      const state = { nextId: 2, todos: [todo(1)] };
      await saveState(filePath, state);
      const raw = await readFile(filePath, 'utf8');
      assert.equal(raw, serializeState(state));
      assert.ok(raw.endsWith('}\n'));
      assert.deepEqual(JSON.parse(raw), state);
    });

    it('replaces the previous contents entirely', async () => {
      await saveState(filePath, { nextId: 3, todos: [todo(1), todo(2)] });
      await saveState(filePath, { nextId: 3, todos: [] });
      assert.deepEqual(JSON.parse(await readFile(filePath, 'utf8')), { nextId: 3, todos: [] });
    });

    it('leaves no temporary files behind', async () => {
      await saveState(filePath, { nextId: 1, todos: [] });
      assert.deepEqual(await listDir(dir), ['todos.json']);
    });

    it('fails with StorageError and no temp files when the directory is not writable', { skip: !canTestPermissions }, async () => {
      await chmod(dir, 0o555);
      try {
        await assert.rejects(saveState(filePath, { nextId: 1, todos: [] }), {
          name: 'StorageError',
          message: /Could not write .*todos\.json/,
        });
      } finally {
        await chmod(dir, 0o755);
      }
      assert.deepEqual(await listDir(dir), []);
    });
  });

  describe('withFileLock', () => {
    it('returns the callback result and removes the lock file afterwards', async () => {
      const result = await withFileLock(filePath, async () => {
        assert.ok((await listDir(dir)).includes('todos.json.lock'), 'lock should exist while running');
        return 'done';
      });
      assert.equal(result, 'done');
      assert.deepEqual(await listDir(dir), []);
    });

    it('removes the lock file and rethrows when the callback fails', async () => {
      const failure = new Error('boom');
      await assert.rejects(withFileLock(filePath, async () => { throw failure; }), (error) => error === failure);
      assert.deepEqual(await listDir(dir), []);
    });

    it('times out with an actionable message while another holder keeps a fresh lock', async () => {
      await writeFile(`${filePath}.lock`, '12345\n');
      const started = Date.now();
      await assert.rejects(withFileLock(filePath, async () => 'never', { timeoutMs: 100, staleLockMs: 60_000 }), {
        name: 'StorageError',
        message: /Timed out after 100ms .*delete that file and try again/,
      });
      assert.ok(Date.now() - started >= 100, 'should wait at least the timeout');
      assert.ok((await listDir(dir)).includes('todos.json.lock'), 'a live lock must not be removed');
    });

    it('reclaims a stale lock left behind by a crashed process', async () => {
      const lockPath = `${filePath}.lock`;
      await writeFile(lockPath, '12345\n');
      const longAgo = new Date(Date.now() - 60_000);
      await utimes(lockPath, longAgo, longAgo);
      const result = await withFileLock(filePath, async () => 'ran', { timeoutMs: 100, staleLockMs: 1_000 });
      assert.equal(result, 'ran');
      assert.deepEqual(await listDir(dir), []);
    });

    it('serializes concurrent in-process updates so no add is lost', async () => {
      const count = 25;
      const now = new Date(CREATED_AT);
      await Promise.all(
        Array.from({ length: count }, (_, index) =>
          updateState(filePath, (state) => addTodo(state, `parallel ${index}`, { now })),
        ),
      );
      const state = await loadState(filePath);
      assert.equal(state.todos.length, count);
      assert.deepEqual(state.todos.map((t) => t.id).sort((a, b) => a - b), Array.from({ length: count }, (_, i) => i + 1));
      assert.equal(state.nextId, count + 1);
    });
  });

  describe('updateState', () => {
    it('writes nothing when the update throws', async () => {
      const original = '{"nextId":2,"todos":[{"id":1,"text":"a","completed":false,"createdAt":"2026-01-02T03:04:05.678Z"}]}';
      await writeFile(filePath, original);
      await assert.rejects(updateState(filePath, () => { throw new StorageError('nope'); }), { message: 'nope' });
      assert.equal(await readFile(filePath, 'utf8'), original);
      assert.deepEqual((await listDir(dir)).sort(), ['todos.json']);
    });

    it('skips the write when the update reports changed: false', async () => {
      const compact = JSON.stringify({ nextId: 2, todos: [todo(1)] });
      await writeFile(filePath, compact);
      await updateState(filePath, (state) => ({ state, changed: false }));
      assert.equal(await readFile(filePath, 'utf8'), compact, 'file should keep its original formatting');
    });

    it('creates todos.json on the first successful write', async () => {
      await updateState(filePath, (state) => addTodo(state, 'first', { now: new Date(CREATED_AT) }));
      assert.deepEqual(await listDir(dir), ['todos.json']);
      assert.equal((await loadState(filePath)).todos[0].text, 'first');
    });
  });

  it('resolveTodoFile places todos.json directly inside the given directory', () => {
    assert.equal(resolveTodoFile('/some/dir'), path.join('/some/dir', 'todos.json'));
  });
});

