import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { afterEach, beforeEach, describe, it } from 'node:test';

import { run, USAGE } from '../src/cli.js';
import { listDir, makeTempDir, readTodoFile, removeTempDir, runInProcess } from './helpers/harness.js';

const FIXED_NOW = new Date('2026-03-04T05:06:07.890Z');

describe('cli (in-process)', () => {
  let cwd;
  const cli = (...argv) => runInProcess(argv, { cwd, now: () => FIXED_NOW });

  beforeEach(async () => {
    cwd = await makeTempDir();
  });

  afterEach(async () => {
    await removeTempDir(cwd);
  });

  describe('add', () => {
    it('adds a todo, confirms it on stdout, and persists it with the documented fields', async () => {
      const result = await cli('add', 'Buy groceries');
      assert.deepEqual(result, { code: 0, stdout: 'Added todo 1: Buy groceries\n', stderr: '' });
      assert.deepEqual(await readTodoFile(cwd), {
        nextId: 2,
        todos: [{ id: 1, text: 'Buy groceries', completed: false, createdAt: FIXED_NOW.toISOString() }],
      });
    });

    it('joins unquoted words into one todo', async () => {
      const result = await cli('add', 'Buy', 'milk', 'and', 'eggs');
      assert.equal(result.stdout, 'Added todo 1: Buy milk and eggs\n');
    });

    it('trims surrounding whitespace from the text', async () => {
      await cli('add', '   Pay rent   ');
      assert.equal((await readTodoFile(cwd)).todos[0].text, 'Pay rent');
    });

    it('keeps text that starts with a dash instead of treating it as an option', async () => {
      const result = await cli('add', '-5 pushups');
      assert.equal(result.stdout, 'Added todo 1: -5 pushups\n');
    });

    it('allows duplicate text as separate todos with distinct ids', async () => {
      await cli('add', 'same');
      await cli('add', 'same');
      assert.deepEqual((await readTodoFile(cwd)).todos.map((t) => [t.id, t.text]), [[1, 'same'], [2, 'same']]);
    });

    it('honours TODO_MAX_TEXT_LENGTH from the injected environment', async () => {
      const result = await runInProcess(['add', 'abcd'], { cwd, env: { TODO_MAX_TEXT_LENGTH: '3' } });
      assert.equal(result.code, 2);
      assert.match(result.stderr, /too long \(4 characters; the maximum is 3\)/);
      assert.equal(await readTodoFile(cwd), undefined);
    });
  });

  describe('list', () => {
    it('shows each todo with its id, status indicator, and text, then a summary', async () => {
      await cli('add', 'Buy groceries');
      await cli('add', 'Walk the dog');
      await cli('complete', '2');

      const result = await cli('list');
      assert.equal(result.code, 0);
      assert.equal(result.stderr, '');
      assert.equal(
        result.stdout,
        ['1. [ ] Buy groceries', '2. [x] Walk the dog', '', '2 todos: 1 done, 1 pending', ''].join('\n'),
      );
    });

    it('prints a friendly message and exits 0 when there are no todos, without creating a file', async () => {
      const result = await cli('list');
      assert.equal(result.code, 0);
      assert.match(result.stdout, /^No todos yet\./);
      assert.deepEqual(await listDir(cwd), []);
    });

    it('prints the empty message after every todo has been deleted', async () => {
      await cli('add', 'temporary');
      await cli('delete', '1');
      assert.match((await cli('list')).stdout, /^No todos yet\./);
    });
  });

  describe('complete', () => {
    it('marks the todo done and persists the change', async () => {
      await cli('add', 'Buy groceries');
      const result = await cli('complete', '1');
      assert.deepEqual(result, { code: 0, stdout: 'Completed todo 1: Buy groceries\n', stderr: '' });
      assert.equal((await readTodoFile(cwd)).todos[0].completed, true);
    });

    it('only changes the targeted todo', async () => {
      await cli('add', 'a');
      await cli('add', 'b');
      await cli('complete', '1');
      assert.deepEqual((await readTodoFile(cwd)).todos.map((t) => t.completed), [true, false]);
    });

    it('reports an already completed todo without failing or rewriting the file', async () => {
      await cli('add', 'Buy groceries');
      await cli('complete', '1');
      const before = await readFile(path.join(cwd, 'todos.json'), 'utf8');

      const result = await cli('complete', '1');
      assert.deepEqual(result, { code: 0, stdout: 'Todo 1 is already completed: Buy groceries\n', stderr: '' });
      assert.equal(await readFile(path.join(cwd, 'todos.json'), 'utf8'), before);
    });
  });

  describe('delete', () => {
    it('removes the todo and confirms which one was deleted', async () => {
      await cli('add', 'a');
      await cli('add', 'b');
      const result = await cli('delete', '1');
      assert.deepEqual(result, { code: 0, stdout: 'Deleted todo 1: a\n', stderr: '' });
      assert.deepEqual((await readTodoFile(cwd)).todos.map((t) => t.id), [2]);
    });

    it('can delete a completed todo', async () => {
      await cli('add', 'done already');
      await cli('complete', '1');
      assert.equal((await cli('delete', '1')).code, 0);
      assert.deepEqual((await readTodoFile(cwd)).todos, []);
    });
  });

  describe('help and usage', () => {
    for (const flag of ['help', '--help', '-h']) {
      it(`"${flag}" prints usage to stdout and exits 0`, async () => {
        assert.deepEqual(await cli(flag), { code: 0, stdout: `${USAGE}\n`, stderr: '' });
      });
    }

    it('lists every command in the usage text', () => {
      for (const command of ['add <text>', 'list', 'complete <id>', 'delete <id>']) {
        assert.ok(USAGE.includes(command), `usage should mention ${command}`);
      }
    });

    it('exits 2 with usage on stderr when no command is given', async () => {
      const result = await cli();
      assert.equal(result.code, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.startsWith('Error: No command given.\n'));
      assert.ok(result.stderr.includes(USAGE));
    });

    it('exits 2 for an unknown command and names it', async () => {
      const result = await cli('remove', '1');
      assert.equal(result.code, 2);
      assert.match(result.stderr, /^Error: Unknown command "remove"\./);
    });

    it('treats command names case-sensitively', async () => {
      assert.equal((await cli('ADD', 'x')).code, 2);
    });
  });

  describe('error reporting', () => {
    it('exits 2 without touching todos.json when an environment limit is malformed', async () => {
      await writeFile(path.join(cwd, 'todos.json'), '{"todos":[]}');
      const result = await runInProcess(['add', 'x'], { cwd, env: { TODO_LOCK_TIMEOUT_MS: 'soon' } });
      assert.equal(result.code, 2);
      assert.match(result.stderr, /TODO_LOCK_TIMEOUT_MS must be a positive whole number, got "soon"/);
      assert.equal(await readFile(path.join(cwd, 'todos.json'), 'utf8'), '{"todos":[]}');
    });

    it('reports unexpected internal errors with a stack trace and exit code 1 instead of throwing', async () => {
      const stderrChunks = [];
      const code = await run(['list'], {
        cwd,
        env: {},
        stdout: { write() { throw new TypeError('stdout exploded'); } },
        stderr: { write(chunk) { stderrChunks.push(chunk); } },
      });
      assert.equal(code, 1);
      assert.match(stderrChunks.join(''), /^Unexpected error \(this is a bug\): TypeError: stdout exploded\n\s+at /);
    });
  });
});

