      const result = await cli('add', 'Buy groceries');
      assert.deepEqual(result, { code: 0, stdout: 'Added todo 1: Buy groceries\n', stderr: '' });
      assert.deepEqual(await readTodoFile(cwd), {
        nextId: 2,
        todos: [{ id: 1, text: 'Buy groceries', completed: false, createdAt: FIXED_NOW.toISOString() }],
      });
    });

    it('joins unquoted words into one todo', async () => {
      const result = await cli('add', 'Buy', 'milk', 'and', 'eggs');
      assert.equal(result.stdout, 'Added todo 1: Buy milk and eggs\n');
    });

    it('trims surrounding whitespace from the text', async () => {
      await cli('add', '   Pay rent   ');
      assert.equal((await readTodoFile(cwd)).todos[0].text, 'Pay rent');
    });

    it('keeps text that starts with a dash instead of treating it as an option', async () => {
      const result = await cli('add', '-5 pushups');
      assert.equal(result.stdout, 'Added todo 1: -5 pushups\n');
    });

    it('allows duplicate text as separate todos with distinct ids', async () => {
      await cli('add', 'same');
      await cli('add', 'same');
      assert.deepEqual((await readTodoFile(cwd)).todos.map((t) => [t.id, t.text]), [[1, 'same'], [2, 'same']]);
    });

    it('honours TODO_MAX_TEXT_LENGTH from the injected environment', async () => {
      const result = await runInProcess(['add', 'abcd'], { cwd, env: { TODO_MAX_TEXT_LENGTH: '3' } });
      assert.equal(result.code, 2);
      assert.match(result.stderr, /too long \(4 characters; the maximum is 3\)/);
      assert.equal(await readTodoFile(cwd), undefined);
    });
  });

  describe('list', () => {
    it('shows each todo with its id, status indicator, and text, then a summary', async () => {
      await cli('add', 'Buy groceries');
      await cli('add', 'Walk the dog');
      await cli('complete', '2');

      const result = await cli('list');
      assert.equal(result.code, 0);
      assert.equal(result.stderr, '');
      assert.equal(
        result.stdout,
        ['1. [ ] Buy groceries', '2. [x] Walk the dog', '', '2 todos: 1 done, 1 pending', ''].join('\n'),
      );
    });

    it('prints a friendly message and exits 0 when there are no todos, without creating a file', async () => {
      const result = await cli('list');
      assert.equal(result.code, 0);
      assert.match(result.stdout, /^No todos yet\./);
      assert.deepEqual(await listDir(cwd), []);
    });

    it('prints the empty message after every todo has been deleted', async () => {
      await cli('add', 'temporary');
      await cli('delete', '1');
      assert.match((await cli('list')).stdout, /^No todos yet\./);
    });
  });

