import assert from 'node:assert/strict';
import { chmod, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { afterEach, beforeEach, describe, it } from 'node:test';

import { listDir, makeTempDir, readTodoFile, removeTempDir, runInProcess, runNode } from './helpers/harness.js';

const canTestPermissions = process.platform !== 'win32' && process.getuid?.() !== 0;

describe('edge cases and error recovery', () => {
  let cwd;
  let todoFile;
  const cli = (...argv) => runInProcess(argv, { cwd });
  const readRaw = () => readFile(todoFile, 'utf8');

  beforeEach(async () => {
    cwd = await makeTempDir();
    todoFile = path.join(cwd, 'todos.json');
  });

  afterEach(async () => {
    await removeTempDir(cwd);
  });

  describe('missing and extra arguments', () => {
    it('add without text exits 2 with a hint and creates no file', async () => {
      const result = await cli('add');
      assert.equal(result.code, 2);
      assert.match(result.stderr, /^Error: Missing todo text\. Usage: node index\.js add "Buy groceries"/);
      assert.deepEqual(await listDir(cwd), []);
    });

    for (const [label, args] of [
      ['an empty string', ['']],
      ['only spaces', ['   ']],
      ['several blank arguments', ['', ' ', '']],
    ]) {
      it(`add with ${label} is rejected as empty`, async () => {
        const result = await cli('add', ...args);
        assert.equal(result.code, 2);
        assert.match(result.stderr, /Todo text cannot be empty/);
        assert.deepEqual(await listDir(cwd), []);
      });
    }

    for (const command of ['complete', 'delete']) {
      it(`${command} without an id exits 2 and shows the expected syntax`, async () => {
        const result = await cli(command);
        assert.equal(result.code, 2);
        assert.match(result.stderr, new RegExp(`Missing todo id\\. Usage: node index\\.js ${command} <id>`));
      });

      it(`${command} with more than one id exits 2 and changes nothing`, async () => {
        await cli('add', 'a');
        await cli('add', 'b');
        const before = await readRaw();
        const result = await cli(command, '1', '2');
        assert.equal(result.code, 2);
        assert.match(result.stderr, /expected one id, got 2/);
        assert.equal(await readRaw(), before);
      });
    }

    it('list with unexpected arguments exits 2', async () => {
      const result = await cli('list', '--all');
      assert.equal(result.code, 2);
      assert.match(result.stderr, /"list" does not take arguments/);
    });
  });

  describe('invalid and unknown ids', () => {
    for (const command of ['complete', 'delete']) {
      for (const badId of ['abc', '0', '-1', '1.5', '1e2', '', ' ', '0x1']) {
        it(`${command} ${JSON.stringify(badId)} exits 2 as an invalid id and leaves the file unchanged`, async () => {
          await cli('add', 'keep me');
          const before = await readRaw();
          const result = await cli(command, badId);
          assert.equal(result.code, 2);
          assert.match(result.stderr, /Invalid id .*expected a positive whole number/);
          assert.equal(await readRaw(), before);
        });
      }

      it(`${command} of a non-existent id exits 1 and leaves the file unchanged`, async () => {
        await cli('add', 'keep me');
        const before = await readRaw();
        const result = await cli(command, '99');
        assert.equal(result.code, 1);
        assert.match(result.stderr, /^Error: No todo with id 99\. Run "node index\.js list"/);
        assert.equal(await readRaw(), before);
      });

      it(`${command} on an empty list exits 1 without creating todos.json or leaving a lock`, async () => {
        const result = await cli(command, '1');
        assert.equal(result.code, 1);
        assert.match(result.stderr, /No todo with id 1/);
        assert.deepEqual(await listDir(cwd), []);
      });
    }

    it('complete of a deleted id reports it as not found', async () => {
      await cli('add', 'short-lived');
      await cli('delete', '1');
      const result = await cli('complete', '1');
      assert.equal(result.code, 1);
      assert.match(result.stderr, /No todo with id 1/);
    });

    it('deleting the same id twice fails the second time', async () => {
      await cli('add', 'once');
      assert.equal((await cli('delete', '1')).code, 0);
      assert.equal((await cli('delete', '1')).code, 1);
    });

    it('accepts ids with leading zeros', async () => {
      await cli('add', 'padded');
      assert.equal((await cli('complete', '001')).stdout, 'Completed todo 1: padded\n');
    });
  });

  describe('text content', () => {
    for (const text of ['Café ☕', '日本語のタスク', 'مرحبا بالعالم', 'Família 👨‍👩‍👧 🎉', 'e\u0301 combining accent']) {
      it(`round-trips unicode text ${JSON.stringify(text)} through add and list`, async () => {
        await cli('add', text);
        assert.equal((await readTodoFile(cwd)).todos[0].text, text);
        assert.ok((await cli('list')).stdout.startsWith(`1. [ ] ${text}\n`));
      });
    }

    it('accepts text at exactly the default 500-character limit', async () => {
      const result = await cli('add', 'x'.repeat(500));
      assert.equal(result.code, 0);
    });

    it('rejects text over the limit with exit 2 and creates no file', async () => {
      const result = await cli('add', 'x'.repeat(501));
      assert.equal(result.code, 2);
      assert.match(result.stderr, /too long \(501 characters; the maximum is 500\)/);
      assert.deepEqual(await listDir(cwd), []);
    });

    it('rejects a very large input (100k characters) cleanly', async () => {
      const result = await cli('add', 'y'.repeat(100_000));
      assert.equal(result.code, 2);
      assert.match(result.stderr, /too long/);
    });

    it('rejects multi-line text and terminal escape sequences', async () => {
      assert.equal((await cli('add', 'line one\nline two')).code, 2);
      assert.equal((await cli('add', '\u001b[2Jclear screen')).code, 2);
      assert.deepEqual(await listDir(cwd), []);
    });

    it('treats JSON-looking and quote-heavy text as plain text', async () => {
      const text = '{"id": 99, "completed": true} \\ "quoted" \'single\'';
      await cli('add', text);
      const data = await readTodoFile(cwd);
      assert.equal(data.todos[0].text, text);
      assert.equal(data.todos[0].id, 1);
      assert.equal(data.todos[0].completed, false);
    });
  });

  describe('command name lookups', () => {
    for (const name of ['constructor', '__proto__', 'toString', 'hasOwnProperty', 'prototype']) {
      it(`does not resolve the object-prototype key "${name}" as a command`, async () => {
        const result = await cli(name);
        assert.equal(result.code, 2);
        assert.match(result.stderr, /Unknown command/);
      });
    }

    it('escapes control characters when echoing an unknown command', async () => {
      const result = await cli('\u001b[31mred');
      assert.match(result.stderr, /Unknown command "\\u001b\[31mred"/);
      assert.ok(!result.stderr.includes('\u001b'), 'raw ESC must not reach the terminal');
    });
  });

  describe('damaged or unusual todos.json', () => {
    it('list exits 1 with a clear message when todos.json is not valid JSON', async () => {
      await writeFile(todoFile, 'not json at all');
      const result = await cli('list');
      assert.equal(result.code, 1);
      assert.match(result.stderr, /todos\.json is not valid JSON/);
      assert.equal(result.stdout, '');
    });

    for (const command of [['add', 'new'], ['complete', '1'], ['delete', '1']]) {
      it(`${command[0]} refuses to overwrite a corrupt todos.json`, async () => {
        await writeFile(todoFile, '[{"id": 1,');
        const result = await cli(...command);
        assert.equal(result.code, 1);
        assert.equal(await readRaw(), '[{"id": 1,');
        assert.deepEqual(await listDir(cwd), ['todos.json'], 'no lock or temp file should remain');
      });
    }

    it('reports a schema problem with the offending index and field', async () => {
      await writeFile(todoFile, JSON.stringify([{ id: 1, text: 'ok', completed: 'no', createdAt: '2026-01-01T00:00:00.000Z' }]));
      const result = await cli('list');
      assert.equal(result.code, 1);
      assert.match(result.stderr, /todo at index 0 \(id 1\) has an invalid "completed"/);
    });

    it('upgrades a legacy bare-array file to the { nextId, todos } format on the next write', async () => {
      await writeFile(todoFile, JSON.stringify([{ id: 4, text: 'old', completed: false, createdAt: '2026-01-01T00:00:00.000Z' }]));
      const result = await cli('add', 'new');
      assert.equal(result.stdout, 'Added todo 5: new\n');
      const data = await readTodoFile(cwd);
      assert.equal(data.nextId, 6);
      assert.deepEqual(data.todos.map((t) => t.id), [4, 5]);
    });

    it('lists a large file of 2,000 todos with aligned columns', async () => {
      const todos = Array.from({ length: 2000 }, (_, index) => ({
        id: index + 1,
        text: `task ${index + 1}`,
        completed: index % 2 === 0,
        createdAt: '2026-01-01T00:00:00.000Z',
      }));
      await writeFile(todoFile, JSON.stringify({ nextId: 2001, todos }));
      const result = await cli('list');
      assert.equal(result.code, 0);
      const lines = result.stdout.split('\n');
      assert.equal(lines[0], '1.    [x] task 1');
      assert.equal(lines[1999], '2000. [ ] task 2000');
      assert.equal(lines[2001], '2000 todos: 1000 done, 1000 pending');
    });

    it('exits 1 with a readable message when todos.json cannot be read', { skip: !canTestPermissions }, async () => {
      await writeFile(todoFile, '{"todos":[]}');
      await chmod(todoFile, 0o000);
      try {
        const result = await cli('list');
        assert.equal(result.code, 1);
        assert.match(result.stderr, /^Error: Could not read .*todos\.json/);
      } finally {
        await chmod(todoFile, 0o644);
      }
    });
  });

  describe('locking and concurrency', () => {
    it('fails with exit 1 and a lock hint when another command holds the lock too long', async () => {
      await cli('add', 'existing');
      await writeFile(`${todoFile}.lock`, '99999\n');
      const before = await readRaw();

      const result = await runInProcess(['add', 'blocked'], { cwd, env: { TODO_LOCK_TIMEOUT_MS: '50' } });
      assert.equal(result.code, 1);
      assert.match(result.stderr, /Timed out after 50ms .*todos\.json\.lock/);
      assert.equal(await readRaw(), before);
    });

    it('list still works while a write lock is held, because reads never see a partial file', async () => {
      await cli('add', 'visible');
      await writeFile(`${todoFile}.lock`, '99999\n');
      const result = await cli('list');
      assert.equal(result.code, 0);
      assert.match(result.stdout, /visible/);
    });

    it('keeps every todo when several processes run add simultaneously', async () => {
      const count = 8;
      const results = await Promise.all(
        Array.from({ length: count }, (_, index) => runNode(['add', `concurrent ${index}`], { cwd })),
      );
      for (const result of results) {
        assert.equal(result.code, 0, result.stderr);
      }
      const data = await readTodoFile(cwd);
      assert.equal(data.todos.length, count);
      assert.deepEqual(data.todos.map((t) => t.id).sort((a, b) => a - b), Array.from({ length: count }, (_, i) => i + 1));
      assert.deepEqual(
        data.todos.map((t) => t.text).sort(),
        Array.from({ length: count }, (_, i) => `concurrent ${i}`).sort(),
      );
      assert.deepEqual(await listDir(cwd), ['todos.json']);
    });

    it('applies parallel complete and delete commands on different todos without losing either', async () => {
      await cli('add', 'to complete');
      await cli('add', 'to delete');
      await cli('add', 'untouched');

      const [completed, deleted] = await Promise.all([
        runNode(['complete', '1'], { cwd }),
        runNode(['delete', '2'], { cwd }),
      ]);
      assert.equal(completed.code, 0, completed.stderr);
      assert.equal(deleted.code, 0, deleted.stderr);
      assert.deepEqual(
        (await readTodoFile(cwd)).todos.map((t) => [t.id, t.completed]),
        [[1, true], [3, false]],
      );
    });
  });
});

