import assert from 'node:assert/strict';
import { afterEach, beforeEach, describe, it } from 'node:test';

import { listDir, makeTempDir, readTodoFile, removeTempDir, runNode } from './helpers/harness.js';

describe('end-to-end: node index.js', () => {
  let cwd;

  beforeEach(async () => {
    cwd = await makeTempDir();
  });

  afterEach(async () => {
    await removeTempDir(cwd);
  });

  it('runs the full add → list → complete → delete lifecycle across separate processes', async () => {
    const added = await runNode(['add', 'Buy groceries'], { cwd });
    assert.equal(added.code, 0, added.stderr);
    assert.equal(added.stdout, 'Added todo 1: Buy groceries\n');
    assert.equal(added.stderr, '');

    await runNode(['add', 'Walk the dog'], { cwd });

    const listed = await runNode(['list'], { cwd });
    assert.equal(listed.code, 0);
    assert.match(listed.stdout, /^1\. \[ \] Buy groceries$/m);
    assert.match(listed.stdout, /^2\. \[ \] Walk the dog$/m);

    const completed = await runNode(['complete', '1'], { cwd });
    assert.equal(completed.code, 0, completed.stderr);
    assert.equal(completed.stdout, 'Completed todo 1: Buy groceries\n');

    const afterComplete = await runNode(['list'], { cwd });
    assert.match(afterComplete.stdout, /^1\. \[x\] Buy groceries$/m);
    assert.match(afterComplete.stdout, /^2\. \[ \] Walk the dog$/m);
    assert.match(afterComplete.stdout, /2 todos: 1 done, 1 pending/);

    const deleted = await runNode(['delete', '2'], { cwd });
    assert.equal(deleted.code, 0, deleted.stderr);
    assert.equal(deleted.stdout, 'Deleted todo 2: Walk the dog\n');

    const afterDelete = await runNode(['list'], { cwd });
    assert.doesNotMatch(afterDelete.stdout, /Walk the dog/);
    assert.match(afterDelete.stdout, /^1\. \[x\] Buy groceries$/m);
  });

  it('stores todos.json in the current directory with the documented fields', async () => {
    await runNode(['add', 'Buy groceries'], { cwd });

    const data = await readTodoFile(cwd);
    assert.equal(data.todos.length, 1);
    const [todo] = data.todos;
    assert.deepEqual(Object.keys(todo).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(todo.id, 1);
    assert.equal(todo.text, 'Buy groceries');
    assert.equal(todo.completed, false);
    assert.equal(new Date(todo.createdAt).toISOString(), todo.createdAt);
    assert.deepEqual(await listDir(cwd), ['todos.json'], 'no lock or temp files should be left behind');
  });

  it('never reuses the id of a deleted todo, even the highest one', async () => {
    await runNode(['add', 'first'], { cwd });
    await runNode(['add', 'second'], { cwd });
    await runNode(['delete', '2'], { cwd });

    const added = await runNode(['add', 'third'], { cwd });
    assert.equal(added.stdout, 'Added todo 3: third\n');
  });

  it('reports errors on stderr with a non-zero exit code and leaves stdout empty', async () => {
    const result = await runNode(['complete', '42'], { cwd });
    assert.equal(result.code, 1);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /^Error: No todo with id 42\./);
  });

  it('exits with code 2 and prints usage when no command is given', async () => {
    const result = await runNode([], { cwd });
    assert.equal(result.code, 2);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /Usage: node index\.js <command>/);
  });

  it('reads configurable limits from the environment', async () => {
    const result = await runNode(['add', 'too long'], { cwd, env: { TODO_MAX_TEXT_LENGTH: '3' } });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /too long \(8 characters; the maximum is 3\)/);
  });
});

