import { randomUUID } from 'node:crypto';
import { open, readFile, rename, stat, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';

import { DEFAULT_LOCK_TIMEOUT_MS, DEFAULT_STALE_LOCK_MS } from './config.js';
import { StorageError } from './errors.js';
import { createEmptyState } from './todos.js';

export const TODO_FILE_NAME = 'todos.json';
const LOCK_RETRY_DELAY_MS = 20;
const BYTE_ORDER_MARK = '\uFEFF';

/** Path of the todo file for a working directory. */
export function resolveTodoFile(cwd) {
  return path.join(cwd, TODO_FILE_NAME);
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isPositiveSafeInteger(value) {
  return Number.isSafeInteger(value) && value >= 1;
}

function validateTodo(todo, index, fail) {
  const where = `todo at index ${index}`;
  if (!isPlainObject(todo)) {
    fail(`${where} is not an object`);
  }
  if (!isPositiveSafeInteger(todo.id)) {
    fail(`${where} has an invalid "id" (expected a positive integer, got ${JSON.stringify(todo.id)})`);
  }
  if (typeof todo.text !== 'string' || todo.text.trim() === '') {
    fail(`${where} (id ${todo.id}) has an invalid "text" (expected a non-empty string)`);
  }
  if (typeof todo.completed !== 'boolean') {
    fail(`${where} (id ${todo.id}) has an invalid "completed" (expected true or false)`);
  }
  if (typeof todo.createdAt !== 'string' || Number.isNaN(Date.parse(todo.createdAt))) {
    fail(`${where} (id ${todo.id}) has an invalid "createdAt" (expected an ISO 8601 timestamp)`);
  }
}

/**
 * Validates parsed JSON and returns a state object. Accepts the current
 * `{ nextId, todos }` shape and a bare array of todos (for hand-written or
 * older files), deriving `nextId` from the highest id when it is missing or
 * too small.
 */
function validateState(data, source) {
  const fail = (reason) => {
    throw new StorageError(`${source} is invalid: ${reason}. Fix the file by hand or move it aside to start over.`);
  };

  let todos;
  let storedNextId;
  if (Array.isArray(data)) {
    todos = data;
  } else if (isPlainObject(data) && Array.isArray(data.todos)) {
    todos = data.todos;
    storedNextId = data.nextId;
    if (storedNextId !== undefined && !isPositiveSafeInteger(storedNextId)) {
      fail(`"nextId" must be a positive integer, got ${JSON.stringify(storedNextId)}`);
    }
  } else {
    fail('expected an object with a "todos" array');
  }

  const seenIds = new Set();
  let maxId = 0;
  todos.forEach((todo, index) => {
    validateTodo(todo, index, fail);
    if (seenIds.has(todo.id)) {
      fail(`id ${todo.id} appears more than once`);
    }
    seenIds.add(todo.id);
    maxId = Math.max(maxId, todo.id);
  });

  return {
    nextId: Math.max(storedNextId ?? 1, maxId + 1),
    todos: todos.map((todo) => ({ ...todo })),
  };
}

/** Parses the raw file contents. Empty or whitespace-only content is an empty list. */
export function parseState(raw, source = TODO_FILE_NAME) {
  const content = raw.startsWith(BYTE_ORDER_MARK) ? raw.slice(BYTE_ORDER_MARK.length) : raw;
  if (content.trim() === '') {
    return createEmptyState();
  }
  let data;
  try {
    data = JSON.parse(content);
  } catch (error) {
    throw new StorageError(
      `${source} is not valid JSON (${error.message}). Fix the file by hand or move it aside to start over.`,
      { cause: error },
    );
  }
  return validateState(data, source);
}

/** Reads and validates the todo file. A missing file is an empty list; nothing is created. */
export async function loadState(filePath) {
  let raw;
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      return createEmptyState();
    }
    throw new StorageError(`Could not read ${filePath}: ${error.message}`, { cause: error });
  }
  return parseState(raw, filePath);
}

