export function serializeState(state) {
  return `${JSON.stringify({ nextId: state.nextId, todos: state.todos }, null, 2)}\n`;
}

/**
 * Writes state atomically: the JSON goes to a unique temp file in the same
 * directory, is flushed to disk, then renamed over the target. Readers see
