        message += ` (also failed to remove temporary file ${tempPath}: ${cleanupError.message})`;
      }
    }
    throw new StorageError(message, { cause: error });
  }
}

/**
 * Removes the lock if its last modification is older than `staleLockMs`,
 * which means its owner most likely crashed. Returns true when the caller
 * should retry acquiring immediately.
 */
async function clearStaleLock(lockPath, staleLockMs) {
  let lockStat;
