    lockStat = await stat(lockPath);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return true;
    }
    throw new StorageError(`Could not inspect lock file ${lockPath}: ${error.message}`, { cause: error });
  }
  if (Date.now() - lockStat.mtimeMs <= staleLockMs) {
    return false;
  }
  try {
    await unlink(lockPath);
  } catch (error) {
    if (error.code !== 'ENOENT') {
      throw new StorageError(`Could not remove stale lock file ${lockPath}: ${error.message}`, { cause: error });
    }
  }
  return true;
}

async function acquireLock(lockPath, { timeoutMs, staleLockMs }) {
  const deadline = Date.now() + timeoutMs;
  // Sequential on purpose: each attempt runs only after the previous one lost
  // the race, with a short delay so waiting processes do not spin.
  for (;;) {
    try {
      // 'wx' fails with EEXIST if the lock already exists, making creation the atomic test-and-set.
      // The pid is only there for a human inspecting a stuck lock.
      await writeFile(lockPath, `${process.pid}\n`, { encoding: 'utf8', flag: 'wx' });
      return;
    } catch (error) {
      if (error.code !== 'EEXIST') {
        throw new StorageError(`Could not create lock file ${lockPath}: ${error.message}`, { cause: error });
      }
    }
    if (await clearStaleLock(lockPath, staleLockMs)) {
      continue;
    }
    if (Date.now() >= deadline) {
      throw new StorageError(
        `Timed out after ${timeoutMs}ms waiting for another todo command to release ${lockPath}. ` +
          'If no other todo command is running, delete that file and try again.',
      );
    }
    await delay(LOCK_RETRY_DELAY_MS);
  }
}

async function releaseLock(lockPath) {
  try {
    await unlink(lockPath);
  } catch (error) {
    // ENOENT means another process judged our lock stale and removed it;
    // there is nothing left to release.
    if (error.code !== 'ENOENT') {
      throw new StorageError(`Could not remove lock file ${lockPath}: ${error.message}. Delete it by hand.`, {
        cause: error,
      });
    }
  }
}

/**
 * Runs `fn` while holding an exclusive `<filePath>.lock` file, so concurrent
 * CLI processes cannot interleave their read-modify-write cycles. Waits up to
 * `timeoutMs` for the lock; locks untouched for `staleLockMs` are reclaimed.
 */
export async function withFileLock(
  filePath,
  fn,
  { timeoutMs = DEFAULT_LOCK_TIMEOUT_MS, staleLockMs = DEFAULT_STALE_LOCK_MS } = {},
) {
  const lockPath = `${filePath}.lock`;
  await acquireLock(lockPath, { timeoutMs, staleLockMs });
  try {
    return await fn();
  } finally {
    await releaseLock(lockPath);
  }
}

/**
 * Loads state under the lock, passes it to `update`, and saves the result if
 * `update` returns `{ changed: true }` (or omits `changed`). Returns whatever
 * `update` returned. If `update` throws, nothing is written.
 */
export function updateState(filePath, update, lockOptions) {
  return withFileLock(
    filePath,
    async () => {
      const result = update(await loadState(filePath));
      if (result.changed !== false) {
        await saveState(filePath, result.state);
      }
      return result;
    },
    lockOptions,
  );
}

